SELECT data_time AS time, ${field} AS value
FROM ${tableName}
WHERE device_id = #{deviceId}
  AND data_time >= #{start}
  AND data_time <= #{end}
ORDER BY data_time ASC

SELECT data_time, pressure, flow, ph, turbidity, residual_cl, temperature, level
FROM ${tableName}
WHERE device_id = #{deviceId}
  AND data_time >= #{start}
  AND data_time <= #{end}
ORDER BY data_time ASC
